files..github/workflows/apply-daily-gainers-ai:
name: "[07 研究] 套用 5% 法人隔日補查"

on:
  push:
    branches:
      - main
    paths:
      - 'research_pending/daily-gainers-ai-rechecks/*.json'
      - '.github/workflows/apply-daily-gainers-ai-recheck.yml'
  workflow_call:
    inputs:
      date:
        description: '補查日期 YYYYMMDD'
        required: false
        type: string
  workflow_dispatch:
    inputs:
      date:
        description: '補查日期 YYYYMMDD；留空時取最近補查 decision'
        required: false
        type: string

permissions:
  contents: write

concurrency:
  group: daily-gainers-ai-recheck-apply
  cancel-in-progress: false

jobs:
  apply:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v7
        with:
          ref: main
          fetch-depth: 2

      - uses: actions/setup-node@v7
        with:
          node-version: '24'

      - name: Resolve date
        id: date
        shell: bash
        env:
          INPUT_DATE: ${{ inputs.date || github.event.inputs.date }}
          EVENT_NAME: ${{ github.event_name }}
        run: |
          set -euo pipefail
          date="${INPUT_DATE:-}"

          if [ -z "$date" ] && [ "$EVENT_NAME" = "push" ]; then
            changed_path="$(jq -r '[.commits[]? | (.added[]?, .modified[]?)] | map(select(test("^research_pending/daily-gainers-ai-rechecks/20[0-9]{6}\\.json$"))) | last // empty' "$GITHUB_EVENT_PATH")"
            if [ -n "$changed_path" ]; then
              date="$(basename "$changed_path" .json)"
            fi
          fi

          if [ -z "$date" ]; then
            date="$(find research_pending/daily-gainers-ai-rechecks -maxdepth 1 -type f -name '20??????.json' -printf '%f\n' 2>/dev/null | sed 's/\.json$//' | sort | tail -1)"
          fi

          [[ "$date" =~ ^20[0-9]{6}$ ]] || { echo "Invalid or missing date: $date" >&2; exit 1; }

          decision="research_pending/daily-gainers-ai-rechecks/${date}.json"
          [ -s "$decision" ] || { echo "Missing recheck decision: $decision" >&2; exit 1; }
          decision_date="$(jq -r '.target_date // empty' "$decision")"
          [ "$decision_date" = "$date" ] || { echo "Decision target_date mismatch: filename=$date payload=$decision_date" >&2; exit 1; }

          echo "date=$date" >> "$GITHUB_OUTPUT"
          echo "Resolved recheck date: $date"

      - name: Apply verified recheck decision
        shell: bash
        run: |
          set -euo pipefail
          date="${{ steps.date.outputs.date }}"
          node - "$date" <<'NODE'
          const fs = require('node:fs');
          const date = process.argv[2];
          const contract = JSON.parse(fs.readFileSync('config/daily-gainers-ai-contract.json','utf8'));
          const factsPath = `data_daily_gain_over_5/analysis-facts/${date}.json`;
          const pendingPath = `research_pending/daily-gainers-ai/${date}.json`;
          const decisionPath = `research_pending/daily-gainers-ai-rechecks/${date}.json`;
          for (const file of [factsPath,pendingPath,decisionPath]) {
            if (!fs.existsSync(file)) throw new Error(`Missing ${file}`);
          }
          const facts = JSON.parse(fs.readFileSync(factsPath,'utf8'));
          const pending = JSON.parse(fs.readFileSync(pendingPath,'utf8'));
          const decision = JSON.parse(fs.readFileSync(decisionPath,'utf8'));
          if (facts.schema_version !== contract.facts.schema_version || facts.methodology_version !== contract.facts.methodology_version) throw new Error('facts not current contract');
          if (pending.schema_version !== contract.ai.schema_version || pending.methodology_version !== contract.ai.methodology_version || pending.model_role !== contract.ai.model_role) throw new Error('pending not current contract');
          if (facts.target_date !== date || pending.target_date !== date || decision.target_date !== date) throw new Error('target_date mismatch');
          if (!Array.isArray(decision.resolve_from) || !decision.resolve_from.length) throw new Error('decision.resolve_from required');
          if (!contract.institutional_verification.allowed_statuses.includes(decision.status)) throw new Error('decision status not allowed by contract');
          if (decision.status !== 'verified') throw new Error('this deterministic applier only promotes externally verified decisions');
          if (!decision.checked_at || Number.isNaN(Date.parse(decision.checked_at))) throw new Error('decision.checked_at must be a valid timestamp');
          if (!decision.web_verification || !Array.isArray(decision.web_verification.sources) || !decision.web_verification.sources.length) throw new Error('web verification sources required');
          const factByCode = new Map(facts.stocks.map(x => [String(x.code), x]));
          const aiCodes = pending.analyses.map(x => String(x.code));
          const factCodes = facts.stocks.map(x => String(x.code));
          if (JSON.stringify(aiCodes) !== JSON.stringify(factCodes)) throw new Error('pending/facts stock order mismatch');
          let updated = 0;
          for (const item of pending.analyses) {
            const v = item.institutional_verification;
            if (!v || !decision.resolve_from.includes(v.status)) continue;
            const fact = factByCode.get(String(item.code));
            const actors = ['foreign','trust','dealer'].map(key => ({ key, ...(fact?.institutional?.[key] || {}) }));
            const required = actors.filter(x => x.requires_external_verification === true);
            if (!required.length) continue;
            for (const actor of required) {
              if (!contract.institutional_verification.required_record_statuses.includes(actor.record_status)) throw new Error(`unexpected record_status ${actor.record_status} for ${item.code}/${actor.key}`);
              const sourceState = facts.institutional_source_status?.[actor.key]?.status;
              if (sourceState !== 'available') throw new Error(`source not available for ${item.code}/${actor.key}`);
            }
            const actorText = required.map(actor => `${actor.key}:${actor.record_status}`).join(', ');
            item.institutional_verification = {
              status: 'verified',
              summary: `隔日重新查證：該交易日官方法人來源已完整產製且可用；需查證欄位為 ${actorText}。no_record 保持「官方有效日表無該股票紀錄」語意，不改寫成數字 0；zero_net 表示原始列存在且淨額確為 0。repository facts 與本次查證一致。`,
              checked_at: decision.checked_at,
              sources: decision.web_verification.sources
            };
            updated += 1;
          }
          if (!updated) {
            console.log(JSON.stringify({date,updated:0,message:'no matching unresolved items'}));
            process.exit(0);
          }
          pending.generated_at = new Date().toISOString();
          fs.writeFileSync(pendingPath, JSON.stringify(pending, null, 2) + '\n');
          console.log(JSON.stringify({date,updated,pendingPath},null,2));
          NODE

      - name: Validate and commit pending update
        shell: bash
        run: |
          set -euo pipefail
          date="${{ steps.date.outputs.date }}"
          pending="research_pending/daily-gainers-ai/${date}.json"
          node scripts/validate_daily_gainers_ai_analysis.js "$date" "$pending"
          git config user.name "github-actions[bot]"
          git config user.email "41898282+github-actions[bot]@users.noreply.github.com"
          git add -- "$pending"
          if git diff --cached --quiet; then
            echo "No pending AI changes to commit"
            exit 0
          fi
          git commit -m "analysis: recheck institutional data for 5% gainers ${date}"
          for attempt in 1 2 3 4 5; do
            if git push origin HEAD:main; then
              exit 0
            fi
            git fetch origin main
            git rebase origin/main
            sleep 5
          done
          echo "Failed to push rechecked pending AI" >&2
          exit 1

  schedule-timing-summary:
    # schedule-timing-summary:v1
    name: 排程時間摘要
    if: always()
    runs-on: ubuntu-latest
    steps:
      - name: Write schedule timing summary
        shell: bash
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        run: |
          set -euo pipefail
          curl -fsSL https://raw.githubusercontent.com/EasonLiu0913/stock_data/main/scripts/write_workflow_schedule_summary.js | node

files..github/workflows/round-3-candidate-rese:
name: '[08 研究分析] 第三輪獨立事件與市場環境候選策略'

on:
  push:
    branches: [main]
    paths:
      - 'config/strategy-candidate-registry.json'
      - 'scripts/round_3_candidate_research_lib.js'
      - 'scripts/generate_round_3_candidate_research.js'
      - 'tests/round_3_candidate_research.test.js'
      - '.github/workflows/round-3-candidate-research.yml'
  pull_request:
    branches: [main]
    paths:
      - 'config/strategy-candidate-registry.json'
      - 'scripts/round_3_candidate_research_lib.js'
      - 'scripts/generate_round_3_candidate_research.js'
      - 'tests/round_3_candidate_research.test.js'
      - '.github/workflows/round-3-candidate-research.yml'
  workflow_dispatch:
    inputs:
      prediction_date:
        description: '股票母體預測日期 YYYYMMDD；留空使用最新有效預測'
        required: false
        type: string
      cutoff:
        description: '研究資料截止日 YYYYMMDD；不得晚於預測 base_trade_date'
        required: false
        type: string
      max_files:
        description: '最多讀取幾個價量與融資交易日'
        required: true
        type: number
        default: 80

permissions:
  contents: write

concurrency:
  group: round-3-candidate-research-${{ github.event_name }}-${{ github.ref }}
  cancel-in-progress: false

jobs:
  research:
    runs-on: ubuntu-latest
    timeout-minutes: 35
    steps:
      - uses: actions/checkout@v7
        with:
          ref: ${{ github.event_name == 'pull_request' && github.event.pull_request.head.sha || 'main' }}
          fetch-depth: 0
      - uses: actions/setup-node@v7
        with:
          node-version: '24'
      - name: Validate third-round candidate engine
        run: |
          set -euo pipefail
          node --check scripts/round_3_candidate_research_lib.js
          node --check scripts/generate_round_3_candidate_research.js
          node --test tests/round_3_candidate_research.test.js
          node - <<'NODE'
          const registry = require('./config/strategy-candidate-registry.json');
          if (registry.status !== 'research_only') throw new Error('Candidate registry must remain research_only');
          if (registry.cooldown_trading_days !== 5) throw new Error('Expected five-trading-day cooldown');
          const definitions = [...registry.candidate_tags, ...registry.candidate_strategies];
          const ids = definitions.map(item => item.candidate_id);
          if (new Set(ids).size !== ids.length) throw new Error('Duplicate candidate IDs');
          for (const definition of definitions) {
            if (!definition.promotion_gate) throw new Error(`Promotion gate missing: ${definition.candidate_id}`);
          }
          NODE
      - name: Confirm formal strategies are untouched
        if: github.event_name == 'pull_request'
        run: |
          set -euo pipefail
          git fetch origin main
          if ! git diff --quiet origin/main...HEAD -- config/strategy-tag-registry.json; then
            echo 'Third-round research must not modify the formal strategy registry.' >&2
            git diff origin/main...HEAD -- config/strategy-tag-registry.json
            exit 1
          fi
      - name: Generate independent event and regime research
        env:
          INPUT_PREDICTION_DATE: ${{ inputs.prediction_date }}
          INPUT_CUTOFF: ${{ inputs.cutoff }}
          INPUT_MAX_FILES: ${{ inputs.max_files }}
        shell: bash
        run: |
          set -euo pipefail
          args=(--max-files "${INPUT_MAX_FILES:-80}")
          if [ -n "${INPUT_PREDICTION_DATE:-}" ]; then args+=(--prediction-date "$INPUT_PREDICTION_DATE"); fi
          if [ -n "${INPUT_CUTOFF:-}" ]; then args+=(--cutoff "$INPUT_CUTOFF"); fi
          node scripts/generate_round_3_candidate_research.js "${args[@]}" \
            | tee /tmp/round-3-candidate-research-result.json
      - name: Verify research safeguards and output
        run: |
          node - <<'NODE'
          const fs = require('node:fs');
          const result = JSON.parse(fs.readFileSync('/tmp/round-3-candidate-research-result.json', 'utf8'));
          if (!result.output_file || !fs.existsSync(result.output_file)) throw new Error('Full research output missing');
          if (!result.summary_file || !fs.existsSync(result.summary_file)) throw new Error('Compact research summary missing');
          const payload = JSON.parse(fs.readFileSync(result.output_file, 'utf8'));
          const summary = JSON.parse(fs.readFileSync(result.summary_file, 'utf8'));
          if (payload.research_id !== 'round_3_independent_regime_candidate_study_v1') throw new Error('Unexpected research ID');
          if (payload.candidate_registry_status !== 'research_only') throw new Error('Candidate registry escaped research-only status');
          if (payload.leakage_guard?.signal_features_use_dates_lte_signal_date !== true) throw new Error('Signal leakage guard missing');
          if (payload.leakage_guard?.random_split_used !== false) throw new Error('Random split must not be used');
          if (payload.leakage_guard?.formal_strategy_registry_modified !== false) throw new Error('Formal strategy isolation missing');
          if (payload.cooldown_trading_days !== 5) throw new Error('Cooldown is not five trading days');
          const expectedIds = [
            'margin_crowding_weakening_v2',
            'margin_exit_relative_resilience_candidate_v1',
            'strong_pullback_quality_candidate_v1',
            'breakout_quality_confirmation_candidate_v1',
          ];
          for (const id of expectedIds) {
            if (!payload.summaries?.[id]) throw new Error(`Candidate summary missing: ${id}`);
            if (!summary.summaries?.[id]) throw new Error(`Compact candidate summary missing: ${id}`);
            if (!payload.summaries[id].promotion_assessment) throw new Error(`Promotion assessment missing: ${id}`);
            for (const split of ['train', 'validation', 'test']) {
              if (payload.summaries[id][split]?.event_count === undefined) {
                throw new Error(`Chronological split missing: ${id}/${split}`);
              }
            }
          }
          const orderedDates = Array.isArray(payload.eligible_signal_dates)
            ? payload.eligible_signal_dates
            : [];
          if (!orderedDates.length) throw new Error('Eligible signal dates missing');
          const dateIndex = new Map(orderedDates.map((date, index) => [date, index]));
          const last = new Map();
          for (const event of payload.events) {
            const key = `${event.candidate_id}::${event.stock_code}`;
            const current = dateIndex.get(event.signal_date);
            const previous = last.get(key);
            if (Number.isInteger(previous) && Number.isInteger(current) && current - previous < payload.cooldown_trading_days) {
              throw new Error(`Cooldown violation: ${key}/${event.signal_date}`);
            }
            last.set(key, current);
          }
          if (summary.events !== undefined || summary.cooldown_suppressed_events !== undefined) {
            throw new Error('Compact summary contains event rows');
          }
          if (summary.independent_event_count !== payload.events.length) throw new Error('Independent event count mismatch');
          if (summary.cooldown_suppressed_count !== payload.cooldown_suppressed_events.length) {
            throw new Error('Suppressed event count mismatch');
          }
          console.log(`Verified ${payload.events.length} independent events; suppressed ${payload.cooldown_suppressed_events.length} repeated signals.`);
          NODE
      - name: Commit third-round research output
        if: github.event_name != 'pull_request'
        shell: bash
        run: |
          set -euo pipefail
          git config user.name 'github-actions[bot]'
          git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
          git add data_research/strategy-factors/round-3
          if git diff --cached --quiet; then
            echo 'No third-round research changes'
            exit 0
          fi
          cutoff=$(node -e "const r=require('/tmp/round-3-candidate-research-result.json');process.stdout.write(r.cutoff_date)")
          git commit -m "data: update round-three candidate research ${cutoff}"
          for attempt in 1 2 3 4 5; do
            if git pull --rebase origin main && git push origin HEAD:main; then exit 0; fi
            git rebase --abort 2>/dev/null || true
            sleep $((attempt * 5))
          done
          exit 1

  schedule-timing-summary:
    # schedule-timing-summary:v1
    name: 排程時間摘要
    if: always()
    runs-on: ubuntu-latest
    steps:
      - name: Write schedule timing summary
        shell: bash
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        run: |
          set -euo pipefail
          curl -fsSL https://raw.githubusercontent.com/EasonLiu0913/stock_data/main/scripts/write_workflow_schedule_summary.js | node

files..github/workflows/round-4-walk-forward-r:
name: '[08 研究分析] 第四輪 Walk-Forward 與尾部風險候選策略'

on:
  push:
    branches: [main]
    paths:
      - 'config/strategy-candidate-registry-round-4.json'
      - 'scripts/round_4_walk_forward_research_lib.js'
      - 'scripts/generate_round_4_walk_forward_research.js'
      - 'tests/round_4_walk_forward_research.test.js'
      - '.github/workflows/round-4-walk-forward-research.yml'
  pull_request:
    branches: [main]
    paths:
      - 'config/strategy-candidate-registry-round-4.json'
      - 'scripts/round_4_walk_forward_research_lib.js'
      - 'scripts/generate_round_4_walk_forward_research.js'
      - 'tests/round_4_walk_forward_research.test.js'
      - '.github/workflows/round-4-walk-forward-research.yml'
  workflow_dispatch:
    inputs:
      prediction_date:
        description: '股票母體預測日期 YYYYMMDD；留空使用最新有效預測'
        required: false
        type: string
      cutoff:
        description: '研究資料截止日 YYYYMMDD；不得晚於預測 base_trade_date'
        required: false
        type: string
      max_files:
        description: '最多讀取幾個價量與融資交易日'
        required: true
        type: number
        default: 80

permissions:
  contents: write

concurrency:
  group: round-4-walk-forward-research-${{ github.event_name }}-${{ github.ref }}
  cancel-in-progress: false

jobs:
  research:
    runs-on: ubuntu-latest
    timeout-minutes: 40
    steps:
      - uses: actions/checkout@v7
        with:
          ref: ${{ github.event_name == 'pull_request' && github.event.pull_request.head.sha || 'main' }}
          fetch-depth: 0
      - uses: actions/setup-node@v7
        with:
          node-version: '24'
      - name: Validate fourth-round research engine
        run: |
          set -euo pipefail
          node --check scripts/round_4_walk_forward_research_lib.js
          node --check scripts/generate_round_4_walk_forward_research.js
          node --test tests/round_4_walk_forward_research.test.js
          node - <<'NODE'
          const registry = require('./config/strategy-candidate-registry-round-4.json');
          if (registry.status !== 'research_only') throw new Error('Fourth-round registry must remain research_only');
          if (registry.cooldown_trading_days !== 5) throw new Error('Expected five-trading-day cooldown');
          if (registry.walk_forward?.purge_days !== 5) throw new Error('Expected five-trading-day purge gap');
          const definitions = registry.candidate_definitions || [];
          const ids = definitions.map(item => item.candidate_id);
          if (!definitions.length || new Set(ids).size !== ids.length) throw new Error('Missing or duplicate candidate IDs');
          for (const definition of definitions) {
            if (!definition.base_candidate_id) throw new Error(`Base candidate missing: ${definition.candidate_id}`);
            if (!definition.promotion_gate) throw new Error(`Promotion gate missing: ${definition.candidate_id}`);
          }
          NODE
      - name: Confirm workflow and formal strategy isolation
        shell: bash
        run: |
          set -euo pipefail
          node - <<'NODE'
          const fs = require('node:fs');
          const text = fs.readFileSync('.github/workflows/round-4-walk-forward-research.yml', 'utf8');
          const forbiddenEvent = ['workflow', 'run'].join('_');
          const forbiddenDeploy = ['deploy', 'pages.yml'].join('-');
          const localWorkflowCall = /uses:\s*\.\/.github\/workflows\//;
          if (text.includes(forbiddenEvent) || text.includes(forbiddenDeploy) || localWorkflowCall.test(text)) {
            throw new Error('Fourth-round research must not chain workflows or deploy Pages');
          }
          NODE
          if [ "${{ github.event_name }}" = 'pull_request' ]; then
            git fetch origin main
            if ! git diff --quiet origin/main...HEAD -- config/strategy-tag-registry.json; then
              echo 'Fourth-round research must not modify the formal strategy registry.' >&2
              git diff origin/main...HEAD -- config/strategy-tag-registry.json
              exit 1
            fi
          fi
      - name: Generate rolling walk-forward and tail-risk research
        env:
          INPUT_PREDICTION_DATE: ${{ inputs.prediction_date }}
          INPUT_CUTOFF: ${{ inputs.cutoff }}
          INPUT_MAX_FILES: ${{ inputs.max_files }}
        shell: bash
        run: |
          set -euo pipefail
          args=(--max-files "${INPUT_MAX_FILES:-80}")
          if [ -n "${INPUT_PREDICTION_DATE:-}" ]; then args+=(--prediction-date "$INPUT_PREDICTION_DATE"); fi
          if [ -n "${INPUT_CUTOFF:-}" ]; then args+=(--cutoff "$INPUT_CUTOFF"); fi
          node scripts/generate_round_4_walk_forward_research.js "${args[@]}" \
            | tee /tmp/round-4-walk-forward-research-result.json
      - name: Verify walk-forward, tail-risk, and leakage safeguards
        run: |
          node - <<'NODE'
          const fs = require('node:fs');
          const result = JSON.parse(fs.readFileSync('/tmp/round-4-walk-forward-research-result.json', 'utf8'));
          if (!result.output_file || !fs.existsSync(result.output_file)) throw new Error('Full fourth-round output missing');
          if (!result.summary_file || !fs.existsSync(result.summary_file)) throw new Error('Compact fourth-round summary missing');
          const payload = JSON.parse(fs.readFileSync(result.output_file, 'utf8'));
          const summary = JSON.parse(fs.readFileSync(result.summary_file, 'utf8'));
          if (payload.research_id !== 'round_4_walk_forward_tail_risk_candidate_study_v1') throw new Error('Unexpected research ID');
          if (payload.candidate_registry_status !== 'research_only') throw new Error('Registry escaped research-only status');
          if (payload.leakage_guard?.signal_features_use_dates_lte_signal_date !== true) throw new Error('Signal leakage guard missing');
          if (payload.leakage_guard?.candidate_selector_runs_before_candidate_cooldown !== true) throw new Error('Selector/cooldown order guard missing');
          if (payload.leakage_guard?.walk_forward_purge_days !== 5) throw new Error('Walk-forward purge gap is not five days');
          if (payload.leakage_guard?.walk_forward_test_windows_overlap !== false) throw new Error('Test windows must not overlap');
          if (payload.leakage_guard?.random_split_used !== false) throw new Error('Random split must not be used');
          if (payload.leakage_guard?.formal_strategy_registry_modified !== false) throw new Error('Formal strategy isolation missing');
          if (payload.leakage_guard?.automatic_formal_promotion_enabled !== false) throw new Error('Automatic formal promotion must remain disabled');
          if (!Array.isArray(payload.walk_forward_folds) || payload.walk_forward_folds.length < 2) throw new Error('Insufficient walk-forward folds');
          const testDates = [];
          for (const fold of payload.walk_forward_folds) {
            const start = payload.eligible_signal_dates.indexOf(fold.test[0]);
            const end = payload.eligible_signal_dates.indexOf(fold.test[1]);
            if (start < 0 || end < start) throw new Error(`Invalid test boundaries: ${fold.fold_id}`);
            testDates.push(...payload.eligible_signal_dates.slice(start, end + 1));
          }
          if (new Set(testDates).size !== testDates.length) throw new Error('Walk-forward test dates overlap');
          const expectedIds = [
            'margin_crowding_breakdown_risk_v3',
            'margin_crowding_panic_rebound_v1',
            'margin_exit_tail_filtered_v2',
            'strong_pullback_recovery_confirmation_v2',
            'bull_breakout_tail_control_v2',
          ];
          for (const id of expectedIds) {
            const candidate = payload.summaries?.[id];
            if (!candidate) throw new Error(`Candidate summary missing: ${id}`);
            if (!summary.summaries?.[id]) throw new Error(`Compact candidate summary missing: ${id}`);
            if (!candidate.promotion_assessment) throw new Error(`Promotion assessment missing: ${id}`);
            if (!Array.isArray(candidate.folds) || candidate.folds.length !== payload.walk_forward_folds.length) {
              throw new Error(`Fold summaries missing: ${id}`);
            }
            for (const field of ['return_5d_p10_pct', 'return_5d_p05_pct', 'cvar_5pct_return_5d_pct', 'extreme_loss_rate_pct']) {
              if (!(field in candidate.walk_forward_test)) throw new Error(`Tail metric missing: ${id}/${field}`);
            }
          }
          const orderedDates = payload.eligible_signal_dates || [];
          const dateIndex = new Map(orderedDates.map((date, index) => [date, index]));
          const last = new Map();
          for (const event of payload.events) {
            const key = `${event.candidate_id}::${event.stock_code}`;
            const current = dateIndex.get(event.signal_date);
            const previous = last.get(key);
            if (Number.isInteger(previous) && Number.isInteger(current) && current - previous < payload.cooldown_trading_days) {
              throw new Error(`Candidate cooldown violation: ${key}/${event.signal_date}`);
            }
            if (event.outcome?.max_adverse_excursion_5d_pct === undefined) throw new Error('Missing adverse excursion');
            last.set(key, current);
          }
          if (summary.events !== undefined || summary.cooldown_suppressed_events !== undefined) {
            throw new Error('Compact summary contains event rows');
          }
          if (summary.independent_event_count !== payload.events.length) throw new Error('Independent event count mismatch');
          if (summary.cooldown_suppressed_count !== payload.cooldown_suppressed_events.length) {
            throw new Error('Suppressed event count mismatch');
          }
          console.log(`Verified ${payload.walk_forward_folds.length} walk-forward folds and ${payload.events.length} independent fourth-round events.`);
          NODE
      - name: Commit fourth-round research output
        if: github.event_name != 'pull_request'
        shell: bash
        run: |
          set -euo pipefail
          git config user.name 'github-actions[bot]'
          git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
          git add data_research/strategy-factors/round-4
          if git diff --cached --quiet; then
            echo 'No fourth-round research changes'
            exit 0
          fi
          cutoff=$(node -e "const r=require('/tmp/round-4-walk-forward-research-result.json');process.stdout.write(r.cutoff_date)")
          git commit -m "data: update round-four walk-forward research ${cutoff}"
          for attempt in 1 2 3 4 5; do
            if git pull --rebase origin main && git push origin HEAD:main; then exit 0; fi
            git rebase --abort 2>/dev/null || true
            sleep $((attempt * 5))
          done
          exit 1

  schedule-timing-summary:
    # schedule-timing-summary:v1
    name: 排程時間摘要
    if: always()
    runs-on: ubuntu-latest
    steps:
      - name: Write schedule timing summary
        shell: bash
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        run: |
          set -euo pipefail
          curl -fsSL https://raw.githubusercontent.com/EasonLiu0913/stock_data/main/scripts/write_workflow_schedule_summary.js | node

files..github/workflows/round-5-factor-refinem:
name: '[08 研究分析] 第五輪條件消融與市場產業廣度'

on:
  push:
    branches: [main]
    paths:
      - 'config/strategy-candidate-registry-round-5.json'
      - 'scripts/round_5_factor_refinement_lib.js'
      - 'scripts/generate_round_5_factor_refinement.js'
      - 'tests/round_5_factor_refinement.test.js'
      - '.github/workflows/round-5-factor-refinement.yml'
  pull_request:
    branches: [main]
    paths:
      - 'config/strategy-candidate-registry-round-5.json'
      - 'scripts/round_5_factor_refinement_lib.js'
      - 'scripts/generate_round_5_factor_refinement.js'
      - 'tests/round_5_factor_refinement.test.js'
      - '.github/workflows/round-5-factor-refinement.yml'
  workflow_dispatch:
    inputs:
      prediction_date:
        description: '股票母體預測日期 YYYYMMDD；留空使用最新有效預測'
        required: false
        type: string
      cutoff:
        description: '研究資料截止日 YYYYMMDD；不得晚於預測 base_trade_date'
        required: false
        type: string
      max_files:
        description: '最多讀取幾個價量與融資交易日'
        required: true
        type: number
        default: 160

permissions:
  contents: write

concurrency:
  group: round-5-factor-refinement-${{ github.event_name }}-${{ github.ref }}
  cancel-in-progress: false

jobs:
  research:
    runs-on: ubuntu-latest
    timeout-minutes: 50
    steps:
      - uses: actions/checkout@v7
        with:
          ref: ${{ github.event_name == 'pull_request' && github.event.pull_request.head.sha || 'main' }}
          fetch-depth: 0

      - uses: actions/setup-node@v7
        with:
          node-version: '24'

      - name: Validate fifth-round research engine
        run: |
          set -euo pipefail
          node --check scripts/round_5_factor_refinement_lib.js
          node --check scripts/generate_round_5_factor_refinement.js
          node --test tests/round_5_factor_refinement.test.js
          node - <<'NODE'
          const registry = require('./config/strategy-candidate-registry-round-5.json');
          if (registry.status !== 'research_only') throw new Error('Fifth-round registry must remain research_only');
          if (registry.cooldown_trading_days !== 5) throw new Error('Expected five-trading-day cooldown');
          if (registry.walk_forward?.purge_days !== 5) throw new Error('Expected five-trading-day purge gap');
          const definitions = registry.candidate_definitions || [];
          const ids = definitions.map(item => item.candidate_id);
          if (definitions.length !== 12) throw new Error(`Expected 12 definitions, received ${definitions.length}`);
          if (new Set(ids).size !== ids.length) throw new Error('Duplicate fifth-round candidate IDs');
          const ablations = definitions.filter(item => item.analysis_role === 'ablation');
          const breadth = definitions.filter(item => item.analysis_role === 'breadth_variant');
          if (ablations.length !== 6) throw new Error('Expected one reference plus five pullback ablations');
          if (breadth.length !== 3) throw new Error('Expected three breakout breadth variants');
          NODE

      - name: Confirm workflow and formal strategy isolation
        shell: bash
        run: |
          set -euo pipefail
          node - <<'NODE'
          const fs = require('node:fs');
          const text = fs.readFileSync('.github/workflows/round-5-factor-refinement.yml', 'utf8');
          const forbiddenEvent = ['workflow', 'run'].join('_');
          const forbiddenDeploy = ['deploy', 'pages.yml'].join('-');
          const localWorkflowCall = /uses:\s*\.\/.github\/workflows\//;
          if (text.includes(forbiddenEvent) || text.includes(forbiddenDeploy) || localWorkflowCall.test(text)) {
            throw new Error('Fifth-round research must not chain workflows or deploy Pages');
          }
          NODE
          if [ "${{ github.event_name }}" = 'pull_request' ]; then
            git fetch origin main
            if ! git diff --quiet origin/main...HEAD -- config/strategy-tag-registry.json; then
              echo 'Fifth-round research must not modify the formal strategy registry.' >&2
              git diff origin/main...HEAD -- config/strategy-tag-registry.json
              exit 1
            fi
          fi

      - name: Generate ablation, direction-reversal, and breadth research
        env:
          INPUT_PREDICTION_DATE: ${{ inputs.prediction_date }}
          INPUT_CUTOFF: ${{ inputs.cutoff }}
          INPUT_MAX_FILES: ${{ inputs.max_files }}
        shell: bash
        run: |
          set -euo pipefail
          args=(--max-files "${INPUT_MAX_FILES:-160}")
          if [ -n "${INPUT_PREDICTION_DATE:-}" ]; then args+=(--prediction-date "$INPUT_PREDICTION_DATE"); fi
          if [ -n "${INPUT_CUTOFF:-}" ]; then args+=(--cutoff "$INPUT_CUTOFF"); fi
          node scripts/generate_round_5_factor_refinement.js "${args[@]}" \
            | tee /tmp/round-5-factor-refinement-result.json

      - name: Verify research output and safeguards
        run: |
          node - <<'NODE'
          const fs = require('node:fs');
          const result = JSON.parse(fs.readFileSync('/tmp/round-5-factor-refinement-result.json', 'utf8'));
          if (!result.output_file || !fs.existsSync(result.output_file)) throw new Error('Full fifth-round output missing');
          if (!result.summary_file || !fs.existsSync(result.summary_file)) throw new Error('Compact fifth-round summary missing');
          const payload = JSON.parse(fs.readFileSync(result.output_file, 'utf8'));
          const summary = JSON.parse(fs.readFileSync(result.summary_file, 'utf8'));
          if (payload.research_id !== 'round_5_factor_refinement_ablation_breadth_study_v1') {
            throw new Error('Unexpected fifth-round research ID');
          }
          if (payload.candidate_registry_status !== 'research_only') throw new Error('Registry escaped research-only status');
          if (payload.source_file_count?.price < 80) throw new Error('Insufficient price history');
          if (payload.source_file_count?.margin_failures !== 0) throw new Error('Margin source failures detected');
          if (!Array.isArray(payload.walk_forward_folds) || payload.walk_forward_folds.length < 3) {
            throw new Error('Insufficient walk-forward folds');
          }
          const guard = payload.leakage_guard || {};
          if (guard.signal_features_use_dates_lte_signal_date !== true) throw new Error('Signal leakage guard missing');
          if (guard.breadth_uses_signal_date_cross_section_only !== true) throw new Error('Breadth leakage guard missing');
          if (guard.direction_reversal_reuses_prior_selector_without_retuning !== true) {
            throw new Error('Direction-reversal selector guard missing');
          }
          if (guard.walk_forward_purge_days !== 5 || guard.walk_forward_test_windows_overlap !== false) {
            throw new Error('Walk-forward purge or overlap guard failed');
          }
          if (guard.formal_strategy_registry_modified !== false || guard.automatic_formal_promotion_enabled !== false) {
            throw new Error('Formal strategy isolation failed');
          }
          const expectedIds = [
            'margin_crowding_breakdown_relative_resilience_v1',
            'margin_crowding_capitulation_continuation_risk_v1',
            'margin_exit_tail_filtered_watch_v2',
            'strong_pullback_recovery_full_reference_v2',
            'strong_pullback_ablation_without_positive_day_v1',
            'strong_pullback_ablation_without_sma20_band_v1',
            'strong_pullback_ablation_without_market_strength_v1',
            'strong_pullback_ablation_without_drawdown_guard_v1',
            'strong_pullback_ablation_without_volatility_guard_v1',
            'bull_breakout_market_breadth_v3',
            'bull_breakout_industry_sync_v3',
            'bull_breakout_combined_breadth_v3',
          ];
          for (const id of expectedIds) {
            if (!payload.summaries?.[id] || !summary.summaries?.[id]) {
              throw new Error(`Candidate summary missing: ${id}`);
            }
          }
          const ablation = payload.ablation_comparison?.strong_pullback_recovery_v2;
          if (!ablation || ablation.rows?.length !== 6) throw new Error('Pullback ablation table is incomplete');
          const breadth = payload.breadth_variant_comparison?.bull_breakout_breadth_v3;
          if (!Array.isArray(breadth) || breadth.length !== 3) throw new Error('Breakout breadth comparison is incomplete');
          const dateIndex = new Map((payload.eligible_signal_dates || []).map((date, index) => [date, index]));
          const last = new Map();
          for (const event of payload.events || []) {
            const key = `${event.candidate_id}::${event.stock_code}`;
            const current = dateIndex.get(event.signal_date);
            const previous = last.get(key);
            if (Number.isInteger(previous) && Number.isInteger(current)
              && current - previous < payload.cooldown_trading_days) {
              throw new Error(`Candidate cooldown violation: ${key}/${event.signal_date}`);
            }
            if (!event.signal?.breadth) throw new Error(`Breadth snapshot missing: ${key}/${event.signal_date}`);
            last.set(key, current);
          }
          if (summary.events !== undefined || summary.cooldown_suppressed_events !== undefined) {
            throw new Error('Compact summary contains event rows');
          }
          if (summary.independent_event_count !== payload.events.length) throw new Error('Independent event count mismatch');
          console.log(`Verified ${payload.walk_forward_folds.length} folds, ${payload.events.length} events, 6 ablations, and 3 breadth variants.`);
          NODE

      - name: Commit fifth-round research output
        if: github.event_name != 'pull_request'
        shell: bash
        run: |
          set -euo pipefail
          git config user.name 'github-actions[bot]'
          git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
          git add data_research/strategy-factors/round-5
          if git diff --cached --quiet; then
            echo 'No fifth-round research changes'
            exit 0
          fi
          cutoff=$(node -e "const r=require('/tmp/round-5-factor-refinement-result.json');process.stdout.write(r.cutoff_date)")
          git commit -m "data: update round-five factor refinement research ${cutoff}"
          for attempt in 1 2 3 4 5; do
            if git pull --rebase origin main && git push origin HEAD:main; then exit 0; fi
            git rebase --abort 2>/dev/null || true
            sleep $((attempt * 5))
          done
          exit 1

  schedule-timing-summary:
    # schedule-timing-summary:v1
    name: 排程時間摘要
    if: always()
    runs-on: ubuntu-latest
    steps:
      - name: Write schedule timing summary
        shell: bash
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        run: |
          set -euo pipefail
          curl -fsSL https://raw.githubusercontent.com/EasonLiu0913/stock_data/main/scripts/write_workflow_schedule_summary.js | node
